function asArray(item) {
  const json = item.json;
  if (Array.isArray(json)) return json;
  if (json && json.data && Array.isArray(json.data.billingPeriods)) return json.data.billingPeriods;
  if (json && Array.isArray(json.billingPeriods)) return json.billingPeriods;
  return [];
}

const contractId = $('Split Contracts').item.json.id;
const periods = $input.all().flatMap(asArray).sort((a, b) => new Date(b.periodStart) - new Date(a.periodStart));
const current = periods[0];
const now = new Date();

// No period at all shouldn't happen (W1.6 always creates #1) but is handled rather than crashing -
// same 'known limitation, not silently assumed correct' discipline as the amendment workflow's own
// 'Pick current period' node.
if (!current) {
  return [{ json: { contractId, needsRollover: false, reason: 'No BillingPeriod found for this Contract at all - unexpected, flagging rather than guessing a start date.' } }];
}

const needsRollover = new Date(current.periodEnd) <= now;
return [{
  json: {
    contractId,
    needsRollover,
    nextPeriodStart: current.periodEnd,
    reason: needsRollover
      ? `Current period ended ${current.periodEnd} - rolling over.`
      : `Current period runs through ${current.periodEnd} - not due yet.`,
  },
}];
